INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('indy-500--1', 54790, '1977-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9idz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5s1g.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indy 500', 'Indy 500 is a 1977 racing video game developed by Atari, Inc. for its Video Computer System (later known as the Atari 2600). It is themed around the Indianapolis 500, and is based on Atari''s earlier 8-player arcade game, Indy 800. Indy 500 was one of the nine launch titles offered when the Atari 2600 went on sale in September 1977. Sears Tele-Games later re-released it as Race; no changes were made to the gameplay. Included with each game was a set of two driving controllers, which were identical in appearance to the 2600 paddle controller but could rotate indefinitely in either direction, among other differences.' FROM games WHERE igdb_id = 54790 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 54790 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
