INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zork', 'Zork is one of the earliest interactive fiction computer games, with roots drawn from the original genre game, Colossal Cave Adventure. The first version of Zork was written in 1977–1979 using the MDL programming language on a DEC PDP-10 computer.' FROM games WHERE igdb_id = 1944 ON CONFLICT (game_id, language_code) DO NOTHING;
