INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('basic-math', 17258, '1977-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8lcw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctc33.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Basic Math', 'Basic Math (aka Fun With Numbers) is a video game cartridge developed by Atari for its Video Computer System (later known as the Atari 2600). The game was one of the nine launch titles offered when the Atari 2600 went on sale in September 1977. The player''s objective is simple: solve basic arithmetic problems. Game variations determine whether the player solves addition, subtraction, multiplication, or division problems, and whether he/she could select the top number (the console randomly selects the lower number). The player uses the joystick to enter a guess, with sound effects signaling whether it is right or wrong.' FROM games WHERE igdb_id = 17258 ON CONFLICT (game_id, language_code) DO NOTHING;
