INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('surround', 18002, '1977-09-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ldc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq5t5.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Surround', 'Surround was an unofficial port of the arcade game Blockade, released the previous year by Gremlin. As such, it was the first home console version of the game that would become widely known on other platforms as Snake. As with other early Atari games, it was licensed to Sears, which released it under the name Chase. The cartridge was subdivided into 14 different games. The first 12 of these were variations on the Blockade theme. Like its predecessor Blockade and successor Snake, the object of Surround was to maneuver a sprite across the screen, leaving a trail behind. A player wins by forcing the other player to crash into one of the trails. Various options allowed for speed-up, diagonal movement, wrap-around and "erase" (the choice to not draw at a given moment); in addition, the sprites could be set to operate at a beginning "slow" speed, or progressively speed up through five speeds.' FROM games WHERE igdb_id = 18002 ON CONFLICT (game_id, language_code) DO NOTHING;
